import {renderSchemaForm,schemaFields} from './schema-form.js';
import {proposalInput,applyAgentProposal} from './setup-agent.js';

const ENVIRONMENT=new Set(['seeds','town','housing','weather']);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mergeValues(base,patch){const out=structuredClone(base||{});for(const [k,v] of Object.entries(patch||{}))out[k]=v&&typeof v==='object'&&!Array.isArray(v)?mergeValues(out[k],v):structuredClone(v);return out;}
export function inStage(scope,stage,key,group){return scope==='town'?group['x-applies']!=='run'&&(stage===0?ENVIRONMENT.has(key):!ENVIRONMENT.has(key)):stage===1;}
const bucket=scope=>scope==='town'?'townOverrides':scope==='run'?'settings':'operations';
export function replaceStageOverrides(draft,scope,stage,values,schema,groups=null){const next=structuredClone(draft[bucket(scope)]||{});for(const f of schemaFields(schema,{groups:groups||((key,g)=>inStage(scope,stage,key,g))}))delete next[f.group];draft[bucket(scope)]={...next,...values};}
export function applyRegion(draft,region){return {...draft,environmentProfile:region.id,region:region.name,townOverrides:mergeValues(draft.townOverrides,region.overrides),configDirty:true,agentSummaryDirty:!!draft.agentProposal};}
export function wizardDraft(draft,packs){const next=structuredClone(draft);const fresh=!next.preset;
 if(next.wizardVersion!==3){if(next.wizardVersion!==2)next.step=next.step>=3?2:next.step===2?1:0;next.step=(next.step||0)+1;}
 next.wizardVersion=3;next.goals??=fresh?[]:['everything'];if(fresh)next.step=0;
 if(fresh){const t=packs?.towns?.find(t=>t.preset==='small_town')||packs?.towns?.[0];if(t)Object.assign(next,{preset:t.preset,townRef:t.preset,townId:t.townId,townName:t.preset.replaceAll('_',' '),homes:500,townOverrides:mergeValues(next.townOverrides,{town:{houses:500}})});}
 next.townOverrides||={};next.settings||={};next.operations||={};return next;
}
export function selectedGoals(data,draft){return (data?.goals||[]).filter(g=>(draft.goals||['everything']).includes(g.id));}
export function focusGroup(data,draft,scope,stage,key,group){if(!inStage(scope,stage,key,group))return false;if(draft.showAllSettings?.[stage]||draft.goals?.includes('everything'))return true;
 if(scope==='town'&&['town','seeds','gas'].includes(key))return true;
 return selectedGoals(data,draft).some(g=>(scope==='run'?g.run:stage===0?g.environment:g.town).includes(key));
}
export function goalMarkup(data,draft){return `<fieldset class="goal-picker"><legend>Choose one or more areas</legend><div class="goal-grid">${(data?.goals||[]).map(g=>`<label class="goal-card"><input type="checkbox" name="test-goal" value="${esc(g.id)}" ${(draft.goals||[]).includes(g.id)?'checked':''}><span class="goal-icon" aria-hidden="true">${g.icon}</span><strong>${esc(g.title)}</strong><span>${esc(g.description)}</span><small>${esc(g.outcomes)}</small></label>`).join('')}</div></fieldset><p class="field-note">These choices come from the engine guide. Your next pages focus on these areas. Other inputs keep their defaults or your previous edits; every setting remains available in Advanced. Choosing a focus does not skip engine calculations.</p>`;}
export function setupProposal(draft){return {...proposalInput(draft),name:draft.name.trim(),summary:draft.summary||'Review your environment, utility and operating assumptions.',assumptions:draft.assumptions||[],limitations:draft.limitations||[]};}
export function acceptSetup(draft,p){return {...applyAgentProposal(draft,p),scenarioId:draft.scenarioId,scenarioTitle:draft.scenarioTitle,step:3,wizardVersion:3,configDirty:false,agentSummaryDirty:false};}
const at=(value,path)=>path.split('.').reduce((o,k)=>o?.[k],value);
function input(scope,path,label,{min=0,max=200,step=1,note='',suffix=''}={}){return `<label>${label}${suffix?` <span>${suffix}</span>`:''}<input type="number" data-basic-scope="${scope}" data-basic-path="${path}" min="${min}" max="${max}" step="${step}" required></label>${note?`<p class="field-note">${note}</p>`:''}`;}
export function stageMarkup(stage,data,draft){if(!data)return '<div class="help-card" role="status">Loading the engine’s setup settings…</div>';
 const allowed=(scope,key)=>focusGroup(data,draft,scope,stage,key,{'x-applies':scope==='town'?'town':'run'});
 const advanced=`<details class="setup-advanced" id="stage-advanced" ${(draft.advanced?.[stage]??(stage===1&&draft.goals?.length===1&&draft.goals[0]==='operations'))?'open':''}><summary><span>Advanced ${stage===0?'environment':'utility & operations'} settings</span><small>Browse every setting for this stage</small></summary><div class="advanced-body">${draft.goals?.includes('everything')?'':`<label class="show-all-settings"><input id="show-all-settings" type="checkbox" ${draft.showAllSettings?.[stage]?'checked':''}> Show all settings for this step</label>`}<label class="sr-only" for="advanced-filter">Find a setting</label><input id="advanced-filter" type="search" placeholder="Find a setting, e.g. ${stage===0?'pools or temperature':'crew, billing or meter'}"><p class="field-note">Use ⓘ for an input’s effect and limits. Basic and advanced controls edit the same values. Fraction fields use 0–1 (0.15 = 15%).</p>${(stage===0?['town']:['town','run']).map(scope=>`<section ${scope==='run'&&!schemaFields(data.schemas.run,{groups:(key,g)=>focusGroup(data,draft,'run',stage,key,g)}).length?'hidden':''}><h3 class="advanced-section-title">${scope==='town'?(stage===0?'Town, households & weather':'Utility networks & town defaults'):scope==='run'?'Year staffing & workflow':'Map-day operations'}</h3>${scope==='operations'?'<p class="field-note">These controls govern the map’s operations day. Year field staffing and workloads are above.</p>':''}<div data-config-scope="${scope}"></div></section>`).join('')}${stage===1&&(draft.showAllSettings?.[stage]||selectedGoals(data,draft).some(g=>g.map))?'<details id="map-defaults-panel" class="map-defaults-panel"><summary>Map-day operations</summary><p class="field-note">These controls govern the map’s operations day. Defaults follow your town settings; Year field staffing is above.</p><div data-config-scope="operations"></div></details>':''}</div></details>`;
 if(stage===0)return `<div class="setup-basic-grid"><fieldset class="town-size-picker"><legend>Town size · homes</legend><div class="town-size-options">${data.townSizes.map(n=>`<button type="button" data-town-size="${n}" aria-pressed="false" ${n>data.homeLimit?'disabled aria-describedby="town-size-limit"':''}>${n.toLocaleString('en-US')}${n>data.homeLimit?'<small>Not available yet</small>':''}</button>`).join('')}</div><p id="town-size-current" class="field-note" aria-live="polite"></p></fieldset><label>Regional starting point<select id="setup-region-profile"><option value="custom">Custom / keep current values</option>${data.regions.map(r=>`<option value="${esc(r.id)}" ${draft.environmentProfile===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label></div><p id="town-size-limit" class="field-note">Sizes count residential homes, not population. Shops and other sites add customer accounts. This engine supports up to ${data.homeLimit.toLocaleString('en-US')} homes; 50,000 and 500,000 need further engine capacity work. Use Advanced for a custom size within the limit.</p><label for="setup-region">Location / service area <span>Optional</span></label><input id="setup-region" maxlength="200" value="${esc(draft.region||'')}" placeholder="e.g. Albany suburbs, New York"><p class="field-note">The regional starting point sets weather and housing assumptions. The service-area name is a label you can refine.</p>${allowed('town','weather')||allowed('town','housing')?'<div id="environment-preview" class="environment-preview" aria-live="polite"></div>':''}<p class="field-note">${esc(data.regionalNote)}</p>${advanced}`;
 return `<label for="setup-services">Services in this town</label><select id="setup-services"><option value="mixed">Electricity + water + gas districts</option><option value="electric">Electricity + water · all-electric heating</option></select><p class="field-note">Electricity and water serve every town. Gas availability varies by district; Advanced lets you adjust its coverage.</p><div class="setup-basic-grid">${allowed('run','reading')?input('run','reading.ami_missed_read','AMI missed-read share',{max:1,step:'any',suffix:'0–1; 0.05 = 5%'}):''}${allowed('run','vee')?input('run','vee.high_ratio','High-reading threshold',{min:1.1,max:10,step:'any',suffix:'multiple of expected use'}):''}${allowed('run','billing')?input('run','billing.high_bill_ratio','High-bill threshold',{min:1.1,max:20,step:'any',suffix:'multiple of normal bill'}):''}${allowed('run','process')?input('run','process.analysts','Billing analysts'):''}${allowed('run','contact')?input('run','contact.agents','Contact-centre agents'):''}${allowed('run','field')?input('run','field.crew_meter.per_1000_premises','Meter technicians',{max:20,step:'any',suffix:'crews / 1,000 premises'}):''}${allowed('run','field')?input('run','field.crew_emergency.per_1000_premises','On-call responders',{max:20,step:'any',suffix:'crews / 1,000 premises'}):''}</div>${allowed('run','field')?'<p class="field-note">Year field crews scale with total premises, including commercial sites. A fraction represents part of a crew’s time. Advanced includes electric, water, gas and construction crews, work types and costs.</p>':''}${advanced}`;
}

export function installStageControls({root,stage,data,getDraft,onChange,onRegion,onError,getOperationDefaults,onShowAll}){
 if(!data)return {invalid:()=>true};
 const forms={},values={};
 for(const scope of stage===0?['town']:['town','run']){
  values[scope]=mergeValues(data.defaults[scope],getDraft()[bucket(scope)]);
  forms[scope]=renderSchemaForm(root.querySelector(`[data-config-scope="${scope}"]`),data.schemas[scope],{
   values:values[scope],base:data.defaults[scope],groups:(key,g)=>focusGroup(data,getDraft(),scope,stage,key,g),showAdvanced:true,collapsible:true,open:[],baseLabel:'Starting town',
   onChange:overrides=>{replaceStageOverrides(getDraft(),scope,stage,overrides,data.schemas[scope],(key,g)=>focusGroup(data,getDraft(),scope,stage,key,g));onChange();syncBasic();if(scope==='town'&&root.querySelector('#map-defaults-panel'))root.querySelector('#map-defaults-panel').open=false;}
  });
 }
 function syncBasic(){for(const el of root.querySelectorAll('[data-basic-path]')){if(document.activeElement===el)continue;el.value=at(forms[el.dataset.basicScope].values,el.dataset.basicPath)??'';}
  const size=forms.town.values.town.houses;for(const b of root.querySelectorAll('[data-town-size]'))b.setAttribute('aria-pressed',String(Number(b.dataset.townSize)===size));
  const current=root.querySelector('#town-size-current');if(current)current.textContent=`Selected: ${size.toLocaleString('en-US')} homes${data.townSizes.includes(size)?'':' · custom size'}`;
  const services=root.querySelector('#setup-services');if(services)services.value=forms.town.values.gas?.all_electric_district_share===1?'electric':'mixed';
  const preview=root.querySelector('#environment-preview');if(preview){const {weather:w,housing:h,town:t}=forms.town.values;const profile=data.regions.find(r=>r.id===getDraft().environmentProfile);preview.innerHTML=`<strong>${esc(profile?.name||'Your environment')}</strong><p>${esc(profile?.description||'Adjust the town, housing and weather in Advanced.')}</p><dl><div><dt>Winter / summer mean</dt><dd>${esc(w.winter.mean_c)}°C / ${esc(w.summer.mean_c)}°C</dd></div>${focusGroup(data,getDraft(),'town',0,'housing',{'x-applies':'town'})?`<div><dt>Pool share on eligible lots</dt><dd>${Math.round(h.pool_rate*1000)/10}%</dd></div><div><dt>Construction era</dt><dd>Centre ${esc(t.era_core_year)} · +${esc(t.era_span_years)} years toward the edge</dd></div><div><dt>Two-storey homes by era</dt><dd>${Object.values(h.two_storey_share).map(v=>Math.round(v*100)+'%').join(' / ')}</dd></div>`:''}</dl>`;}
 }
 function set(scope,path,value){const [group,key,child]=path.split('.');forms[scope].set(group+'.'+key,child?{...forms[scope].values[group][key],[child]:value}:value);}
 for(const el of root.querySelectorAll('[data-basic-path]'))el.onchange=()=>{if(!el.checkValidity()){el.setAttribute('aria-invalid','true');return;}el.removeAttribute('aria-invalid');set(el.dataset.basicScope,el.dataset.basicPath,Number(el.value));};
 for(const b of root.querySelectorAll('[data-town-size]'))b.onclick=()=>{if(forms.town.invalid()){onError('Fix the highlighted environment settings before changing size.');return;}set('town','town.houses',Number(b.dataset.townSize));};
 const all=root.querySelector('#show-all-settings');if(all)all.onchange=()=>{if(Object.values(forms).some(f=>f.invalid())){all.checked=!all.checked;onError('Fix the highlighted settings first.');return;}onShowAll(all.checked);};
 const services=root.querySelector('#setup-services');if(services)services.onchange=()=>set('town','gas.all_electric_district_share',services.value==='electric'?1:.15);
 const region=root.querySelector('#setup-region-profile');if(region)region.onchange=()=>{if(Object.values(forms).some(f=>f.invalid())){region.value=getDraft().environmentProfile||'custom';onError('Fix the highlighted settings before changing region.');return;}const r=data.regions.find(r=>r.id===region.value);onRegion(r);};
 const map=root.querySelector('#map-defaults-panel');let mapPending=false,mapFailed=false,mapRevision=0;
 if(map)map.ontoggle=async()=>{const revision=++mapRevision;if(!map.open)return;if(forms.operations?.invalid()){onError('Fix the highlighted map settings first.');return;}mapPending=true;mapFailed=false;const box=map.querySelector('[data-config-scope]');box.innerHTML='<p class="field-note" role="status">Loading defaults from your environment…</p>';
  try{const defaults=await getOperationDefaults();if(revision!==mapRevision||!root.contains(map))return;
   forms.operations=renderSchemaForm(box,data.schemas.operations,{values:mergeValues(defaults,getDraft().operations),base:defaults,showAdvanced:true,collapsible:true,open:[],baseLabel:'Your town',onChange:overrides=>{getDraft().operations=overrides;onChange();}});
   forms.operations.filter(root.querySelector('#advanced-filter').value);
  }catch(e){if(revision!==mapRevision||!root.contains(map))return;mapFailed=true;box.textContent='Could not load map-day defaults. Close and reopen this section to retry.';onError(e.message);}finally{if(revision===mapRevision)mapPending=false;}
 };
 root.querySelector('#advanced-filter').oninput=e=>{for(const form of Object.values(forms))form.filter(e.target.value);};
 root.querySelector('#stage-advanced').ontoggle=e=>{(getDraft().advanced||={})[stage]=e.target.open;onChange(false);};
 root.querySelector('#stage-advanced').addEventListener('click',e=>{const b=e.target.closest('.schema-info');if(!b)return;e.preventDefault();const row=b.closest('.has-pop'),open=!row.classList.contains('is-open');row.classList.toggle('is-open',open);b.setAttribute('aria-expanded',String(open));});
 syncBasic();if(map&&getDraft().goals?.length===1&&getDraft().goals[0]==='operations')map.open=true;
 return {invalid:()=>!!(map?.open&&(mapPending||mapFailed))||Object.values(forms).some(f=>f.invalid())||[...root.querySelectorAll('[data-basic-path]')].some(i=>!i.checkValidity()),forms};
}
